import { type SQL, sql } from "drizzle-orm";
import { type AnyPgColumn, customType, timestamp, uuid } from "drizzle-orm/pg-core";

import type { AgencyId, BusinessId } from "@repo/core";

/**
 * Column helpers shared by every schema file. Conventions:
 * - ids are UUIDs generated by PostgreSQL and typed with the branded ids from @repo/core;
 * - every timestamp is `timestamptz` and is read as a JavaScript `Date`;
 * - closed vocabularies are `text` columns with a CHECK constraint built from the same
 *   constant array that types the column, so TypeScript and the database cannot drift apart.
 */

export const createdAt = () =>
  timestamp("created_at", { withTimezone: true }).notNull().defaultNow();

/** Set by the database clock on insert and on every update made through Drizzle. */
export const updatedAt = () =>
  timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => sql`now()`);

export const timestamptz = (name: string) => timestamp(name, { withTimezone: true });

/** `agency_id` and `business_id`, the two columns every table with business data carries. */
export const tenantColumns = () => ({
  agencyId: uuid("agency_id").$type<AgencyId>().notNull(),
  businessId: uuid("business_id").$type<BusinessId>().notNull(),
});

/** `column in ('a', 'b', ...)` for a CHECK constraint. Values are code constants. */
export function oneOf(column: AnyPgColumn, values: readonly string[]): SQL {
  for (const value of values) {
    if (!/^[a-z0-9_.]+$/.test(value)) {
      throw new Error(`Unsafe value for a CHECK constraint: ${value}`);
    }
  }
  return sql`${column} in (${sql.raw(values.map((value) => `'${value}'`).join(", "))})`;
}

/** Full-text search vector. Only ever used as a generated column. */
export const tsvector = customType<{ data: string }>({
  dataType() {
    return "tsvector";
  },
});
